import sys

def calculateTotalCost(items, n):
    if n == 0:
        return 0
    return items[n-1] + calculateTotalCost(items, n-1)

def applyDiscount(totalCost, itemCount):
    if itemCount <= 5:
        discount_rate = 0.05
    elif itemCount <= 10:
        discount_rate = 0.10
    else:
        discount_rate = 0.15
    discount = totalCost * discount_rate
    finalCost = totalCost - discount
    return finalCost

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("0.00")
        return

    n = int(data[0])

    if n == 0:
        print("0.00")
        return

    items = list(map(int, data[1:n+1]))

    totalCost = calculateTotalCost(items, n)
    finalCost = applyDiscount(totalCost, n)
    print("{:.2f}".format(finalCost))

if __name__ == "__main__":
    main()
